// Good example: parallel data fetching
async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then((r) => r.json()),
      fetch('/api/notifications').then((r) => r.json()),
      fetch('/api/settings').then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { views: 0 },
      notifications: [] as { id: number; message: string }[],
      settings: { theme: 'light' },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Views: {analytics.views}</p>
      </section>

      <section>
        <h3>Notifications</h3>
        <p>Unread: {notifications.length}</p>
        <ul>
          {notifications.map((n) => (
            <li key={n.id}>{n.message}</li>
          ))}
        </ul>
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
      </section>
    </div>
  )
}

type Analytics = { views: number }
type Notification = { id: number; message: string }
type Settings = { theme: string }

// Good example: parallel data fetching
async function getDashboardData(): Promise<{
  analytics: Analytics
  notifications: Notification[]
  settings: Settings
}> {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('/api/analytics').then((r) => r.json()),
      fetch('/api/notifications').then((r) => r.json()),
      fetch('/api/settings').then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { views: 0 },
      notifications: [],
      settings: { theme: 'light' },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Views: {analytics.views}</p>
      </section>

      <section>
        <h3>Notifications</h3>
        <p>Unread: {notifications.length}</p>
        <ul>
          {notifications.map((n) => (
            <li key={n.id}>{n.message}</li>
          ))}
        </ul>
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
      </section>
    </div>
  )
}
